-- ---------------------------------------------------------------------------
-- Seed: real published control catalogs for five AI-security / AI-governance
-- frameworks that already exist in public.frameworks.
--
-- WHY. public.framework_controls is the table that holds each framework's real
-- catalog of controls; the frameworks rows advertise a control_count but the
-- catalog was empty for these five. This migration populates the REAL,
-- published controls — every control_ref and title is the verbatim published
-- identifier/title from the source standard; no numbers or names are invented.
-- Sources / editions:
--   * ISO/IEC 42001:2023  — Annex A (A.2–A.10) control objectives & controls (38).
--   * NIST AI RMF 1.0     — all 72 subcategories across GOVERN/MAP/MEASURE/MANAGE
--                           (NIST AI 100-1, January 2023).
--   * OWASP Top 10 for LLM Applications 2025 — LLM01:2025 … LLM10:2025.
--   * Google Secure AI Framework (SAIF) — the six core elements plus the 15
--                           published SAIF Map risks (github.com/google/saif-data).
--   * MITRE ATLAS (2024)  — all 16 tactics (AML.TA####) plus representative
--                           real techniques (AML.T####).
-- Descriptions are concise faithful summaries of each control/risk's published
-- intent. Idempotent (ON CONFLICT (id) DO UPDATE); replays from zero.
-- The frameworks rows already exist; this migration does NOT recreate them.
-- ---------------------------------------------------------------------------

-- framework_controls.org_id was added by the ws01 tenancy sweep via a dynamic
-- EXECUTE format('ALTER TABLE public.%I ADD COLUMN org_id ...') loop, which a
-- static replay parser cannot see. Re-assert it idempotently here so the column
-- is guaranteed present (the catalog rows below set org_id explicitly to the
-- demo org) and the migration replays cleanly from zero.
ALTER TABLE public.framework_controls
  ADD COLUMN IF NOT EXISTS org_id uuid DEFAULT current_user_org_id();

-- =====================================================================
-- 1. ISO/IEC 42001:2023 — Annex A controls (A.2 … A.10)  [framework_id: iso-42001]
-- =====================================================================
INSERT INTO public.framework_controls
  (id, org_id, framework_id, control_ref, domain, title, description, control_type, priority)
VALUES
  ('fc-iso-42001-a-2-2','00000000-0000-0000-0000-000000000001','iso-42001','A.2.2','Policies related to AI','AI policy','The organization shall document an AI policy, established and approved by top management, appropriate to its purpose and aligned with its business strategy and risk tolerance.','governance','high'),
  ('fc-iso-42001-a-2-3','00000000-0000-0000-0000-000000000001','iso-42001','A.2.3','Policies related to AI','Alignment with other organizational policies','The organization shall determine where other policies can be affected by or apply to its AI objectives, and ensure the AI policy is aligned with them.','governance','medium'),
  ('fc-iso-42001-a-2-4','00000000-0000-0000-0000-000000000001','iso-42001','A.2.4','Policies related to AI','Review of the AI policy','The AI policy shall be reviewed at planned intervals, or as changes occur, to ensure its continuing suitability, adequacy and effectiveness.','governance','high'),
  ('fc-iso-42001-a-3-2','00000000-0000-0000-0000-000000000001','iso-42001','A.3.2','Internal organization','AI roles and responsibilities','Roles and responsibilities for AI shall be defined and allocated according to the needs of the organization.','governance','high'),
  ('fc-iso-42001-a-3-3','00000000-0000-0000-0000-000000000001','iso-42001','A.3.3','Internal organization','Reporting of concerns','The organization shall define and put in place a process to report concerns about the organization''s role with respect to an AI system throughout its life cycle.','governance','medium'),
  ('fc-iso-42001-a-4-2','00000000-0000-0000-0000-000000000001','iso-42001','A.4.2','Resources for AI systems','Resource documentation','The organization shall identify and document relevant resources required for the activities at given AI system life cycle stages.','governance','medium'),
  ('fc-iso-42001-a-4-3','00000000-0000-0000-0000-000000000001','iso-42001','A.4.3','Resources for AI systems','Data resources','The organization shall determine and document information about the data resources utilized for the AI system.','governance','medium'),
  ('fc-iso-42001-a-4-4','00000000-0000-0000-0000-000000000001','iso-42001','A.4.4','Resources for AI systems','Tooling resources','The organization shall determine and document information about the tooling resources utilized for the AI system.','governance','medium'),
  ('fc-iso-42001-a-4-5','00000000-0000-0000-0000-000000000001','iso-42001','A.4.5','Resources for AI systems','System and computing resources','The organization shall determine and document the system and computing resources utilized for the AI system.','governance','medium'),
  ('fc-iso-42001-a-4-6','00000000-0000-0000-0000-000000000001','iso-42001','A.4.6','Resources for AI systems','Human resources','The organization shall determine and document the human resources and their competences utilized for the development, deployment and operation of the AI system.','governance','medium'),
  ('fc-iso-42001-a-5-2','00000000-0000-0000-0000-000000000001','iso-42001','A.5.2','Assessing impacts of AI systems','AI system impact assessment process','The organization shall establish a process to assess the potential consequences for individuals, groups of individuals and societies of the AI system throughout its life cycle.','governance','high'),
  ('fc-iso-42001-a-5-3','00000000-0000-0000-0000-000000000001','iso-42001','A.5.3','Assessing impacts of AI systems','Documentation of AI system impact assessments','The organization shall document the results of AI system impact assessments and retain them for a defined period.','governance','high'),
  ('fc-iso-42001-a-5-4','00000000-0000-0000-0000-000000000001','iso-42001','A.5.4','Assessing impacts of AI systems','Assessing AI system impact on individuals or groups of individuals','The organization shall assess and document the potential impacts of AI systems to individuals or groups of individuals throughout the system''s life cycle.','governance','high'),
  ('fc-iso-42001-a-5-5','00000000-0000-0000-0000-000000000001','iso-42001','A.5.5','Assessing impacts of AI systems','Assessing societal impacts of AI systems','The organization shall assess and document the potential societal impacts of AI systems throughout their life cycle.','governance','high'),
  ('fc-iso-42001-a-6-1-2','00000000-0000-0000-0000-000000000001','iso-42001','A.6.1.2','AI system life cycle','Objectives for responsible development of AI system','The organization shall identify and document objectives to guide the responsible development of AI systems, and take those objectives into account.','governance','high'),
  ('fc-iso-42001-a-6-1-3','00000000-0000-0000-0000-000000000001','iso-42001','A.6.1.3','AI system life cycle','Processes for responsible design and development of AI systems','The organization shall define and document the processes for the responsible design and development of the AI systems.','governance','high'),
  ('fc-iso-42001-a-6-2-2','00000000-0000-0000-0000-000000000001','iso-42001','A.6.2.2','AI system life cycle','AI system requirements and specification','The organization shall specify and document requirements for new AI systems or material enhancements to existing systems.','governance','high'),
  ('fc-iso-42001-a-6-2-3','00000000-0000-0000-0000-000000000001','iso-42001','A.6.2.3','AI system life cycle','Documentation of AI system design and development','The organization shall document the AI system design and development based on organizational objectives, documented requirements and specification criteria.','governance','medium'),
  ('fc-iso-42001-a-6-2-4','00000000-0000-0000-0000-000000000001','iso-42001','A.6.2.4','AI system life cycle','AI system verification and validation','The organization shall define and document verification and validation measures for the AI system and specify criteria for their use.','governance','high'),
  ('fc-iso-42001-a-6-2-5','00000000-0000-0000-0000-000000000001','iso-42001','A.6.2.5','AI system life cycle','AI system deployment','The organization shall document a deployment plan and ensure that requirements are met before deploying the AI system.','governance','high'),
  ('fc-iso-42001-a-6-2-6','00000000-0000-0000-0000-000000000001','iso-42001','A.6.2.6','AI system life cycle','AI system operation and monitoring','The organization shall define and document the necessary elements for the ongoing operation and monitoring of the AI system.','governance','high'),
  ('fc-iso-42001-a-6-2-7','00000000-0000-0000-0000-000000000001','iso-42001','A.6.2.7','AI system life cycle','AI system technical documentation','The organization shall determine and provide the technical documentation needed by relevant categories of interested parties.','governance','medium'),
  ('fc-iso-42001-a-6-2-8','00000000-0000-0000-0000-000000000001','iso-42001','A.6.2.8','AI system life cycle','AI system recording of event logs','The organization shall determine at which phases of the AI system life cycle record keeping of event logs should be enabled, and provide such logging capabilities.','governance','high'),
  ('fc-iso-42001-a-7-2','00000000-0000-0000-0000-000000000001','iso-42001','A.7.2','Data for AI systems','Data for development and enhancement of AI system','The organization shall define and document requirements for the data used to develop and enhance the AI system.','governance','medium'),
  ('fc-iso-42001-a-7-3','00000000-0000-0000-0000-000000000001','iso-42001','A.7.3','Data for AI systems','Acquisition of data','The organization shall determine and document details about the acquisition and provenance of data used in the AI system.','governance','medium'),
  ('fc-iso-42001-a-7-4','00000000-0000-0000-0000-000000000001','iso-42001','A.7.4','Data for AI systems','Quality of data for AI systems','The organization shall define and document requirements for data quality and ensure that the data used to develop and operate the AI system meets these requirements.','governance','high'),
  ('fc-iso-42001-a-7-5','00000000-0000-0000-0000-000000000001','iso-42001','A.7.5','Data for AI systems','Data provenance','The organization shall define and document a process for recording the provenance of data used in AI systems over their life cycles.','governance','medium'),
  ('fc-iso-42001-a-7-6','00000000-0000-0000-0000-000000000001','iso-42001','A.7.6','Data for AI systems','Data preparation','The organization shall define and document criteria and methods for the preparation of data for the AI system.','governance','medium'),
  ('fc-iso-42001-a-8-2','00000000-0000-0000-0000-000000000001','iso-42001','A.8.2','Information for interested parties of AI systems','System documentation and information for users','The organization shall determine and provide the necessary information to users of the AI system.','governance','medium'),
  ('fc-iso-42001-a-8-3','00000000-0000-0000-0000-000000000001','iso-42001','A.8.3','Information for interested parties of AI systems','External reporting','The organization shall provide the ability for interested parties to report adverse impacts of the AI system.','governance','medium'),
  ('fc-iso-42001-a-8-4','00000000-0000-0000-0000-000000000001','iso-42001','A.8.4','Information for interested parties of AI systems','Communication of incidents','The organization shall determine and document a plan for communicating incidents to relevant users of the AI system.','governance','high'),
  ('fc-iso-42001-a-8-5','00000000-0000-0000-0000-000000000001','iso-42001','A.8.5','Information for interested parties of AI systems','Information for interested parties','The organization shall determine and document its obligations to report information about the AI system to interested parties.','governance','medium'),
  ('fc-iso-42001-a-9-2','00000000-0000-0000-0000-000000000001','iso-42001','A.9.2','Use of AI systems','Processes for responsible use of AI systems','The organization shall define and document the processes for the responsible use of AI systems.','governance','high'),
  ('fc-iso-42001-a-9-3','00000000-0000-0000-0000-000000000001','iso-42001','A.9.3','Use of AI systems','Objectives for responsible use of AI system','The organization shall identify and document objectives to guide the responsible use of AI systems.','governance','medium'),
  ('fc-iso-42001-a-9-4','00000000-0000-0000-0000-000000000001','iso-42001','A.9.4','Use of AI systems','Intended use of the AI system','The organization shall ensure that the AI system is used according to the intended uses of the AI system and its accompanying documentation.','governance','high'),
  ('fc-iso-42001-a-10-2','00000000-0000-0000-0000-000000000001','iso-42001','A.10.2','Third-party and customer relationships','Allocating responsibilities','The organization shall ensure that responsibilities within its AI system life cycle are allocated between the organization, its partners, suppliers, customers and third parties.','governance','high'),
  ('fc-iso-42001-a-10-3','00000000-0000-0000-0000-000000000001','iso-42001','A.10.3','Third-party and customer relationships','Suppliers','The organization shall establish a process to ensure that its usage of services, products or materials provided by suppliers aligns with the organization''s approach to the responsible development and use of AI systems.','governance','high'),
  ('fc-iso-42001-a-10-4','00000000-0000-0000-0000-000000000001','iso-42001','A.10.4','Third-party and customer relationships','Customers','The organization shall ensure that its responsible approach to the development and use of AI systems considers its customers'' needs and expectations.','governance','medium')
ON CONFLICT (id) DO UPDATE SET
  control_ref = EXCLUDED.control_ref, domain = EXCLUDED.domain,
  title = EXCLUDED.title, description = EXCLUDED.description,
  control_type = EXCLUDED.control_type, priority = EXCLUDED.priority;

-- =====================================================================
-- 2. NIST AI RMF 1.0 — 72 subcategories  [framework_id: nist-ai-rmf]
--    domain = the function (GOVERN / MAP / MEASURE / MANAGE)
-- =====================================================================
INSERT INTO public.framework_controls
  (id, org_id, framework_id, control_ref, domain, title, description, control_type, priority)
VALUES
  -- GOVERN
  ('fc-nist-ai-rmf-govern-1-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 1.1','GOVERN','Legal and regulatory requirements','Legal and regulatory requirements involving AI are understood, managed, and documented.','governance','high'),
  ('fc-nist-ai-rmf-govern-1-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 1.2','GOVERN','Trustworthy AI characteristics in policy','The characteristics of trustworthy AI are integrated into organizational policies, processes, procedures, and practices.','governance','high'),
  ('fc-nist-ai-rmf-govern-1-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 1.3','GOVERN','Risk management activity levels','Processes, procedures, and practices are in place to determine the needed level of risk management activities based on the organization''s risk tolerance.','governance','medium'),
  ('fc-nist-ai-rmf-govern-1-4','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 1.4','GOVERN','Risk management process and outcomes','The risk management process and its outcomes are established through transparent policies, procedures, and other controls based on organizational risk priorities.','governance','medium'),
  ('fc-nist-ai-rmf-govern-1-5','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 1.5','GOVERN','Monitoring and review of risk management','Ongoing monitoring and periodic review of the risk management process and its outcomes are planned, and organizational roles and responsibilities are clearly defined, including determining the frequency of periodic review.','governance','medium'),
  ('fc-nist-ai-rmf-govern-1-6','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 1.6','GOVERN','AI system inventory','Mechanisms are in place to inventory AI systems and are resourced according to organizational risk priorities.','governance','high'),
  ('fc-nist-ai-rmf-govern-1-7','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 1.7','GOVERN','Decommissioning AI systems','Processes and procedures are in place for decommissioning and phasing out AI systems safely and in a manner that does not increase risks or decrease the organization''s trustworthiness.','governance','medium'),
  ('fc-nist-ai-rmf-govern-2-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 2.1','GOVERN','Roles, responsibilities, and communication','Roles and responsibilities and lines of communication related to mapping, measuring, and managing AI risks are documented and are clear to individuals and teams throughout the organization.','governance','high'),
  ('fc-nist-ai-rmf-govern-2-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 2.2','GOVERN','AI risk management training','The organization''s personnel and partners receive AI risk management training to enable them to perform their duties and responsibilities consistent with related policies, procedures, and agreements.','governance','medium'),
  ('fc-nist-ai-rmf-govern-2-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 2.3','GOVERN','Executive responsibility for AI risk','Executive leadership of the organization takes responsibility for decisions about risks associated with AI system development and deployment.','governance','high'),
  ('fc-nist-ai-rmf-govern-3-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 3.1','GOVERN','Diverse decision-making','Decision-making related to mapping, measuring, and managing AI risks throughout the lifecycle is informed by a diverse team (e.g., diversity of demographics, disciplines, experience, expertise, and backgrounds).','governance','medium'),
  ('fc-nist-ai-rmf-govern-3-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 3.2','GOVERN','Human-AI oversight roles','Policies and procedures are in place to define and differentiate roles and responsibilities for human-AI configurations and oversight of AI systems.','governance','high'),
  ('fc-nist-ai-rmf-govern-4-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 4.1','GOVERN','Safety-first organizational culture','Organizational policies and practices are in place to foster a critical thinking and safety-first mindset in the design, development, deployment, and uses of AI systems to minimize potential negative impacts.','governance','high'),
  ('fc-nist-ai-rmf-govern-4-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 4.2','GOVERN','Documenting risks and impacts','Organizational teams document the risks and potential impacts of the AI technology they design, develop, deploy, evaluate, and use, and they communicate about the impacts more broadly.','governance','medium'),
  ('fc-nist-ai-rmf-govern-4-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 4.3','GOVERN','Testing, incident, and information sharing','Organizational practices are in place to enable AI testing, identification of incidents, and information sharing.','governance','medium'),
  ('fc-nist-ai-rmf-govern-5-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 5.1','GOVERN','Collecting external feedback','Organizational policies and practices are in place to collect, consider, prioritize, and integrate feedback from those external to the team that developed or deployed the AI system regarding the potential individual and societal impacts related to AI risks.','governance','medium'),
  ('fc-nist-ai-rmf-govern-5-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 5.2','GOVERN','Incorporating feedback into design','Mechanisms are established to enable the team that developed or deployed AI systems to regularly incorporate adjudicated feedback from relevant AI actors into system design and implementation.','governance','medium'),
  ('fc-nist-ai-rmf-govern-6-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 6.1','GOVERN','Third-party risk policies','Policies and procedures are in place that address AI risks associated with third-party entities, including risks of infringement of a third party''s intellectual property or other rights.','governance','high'),
  ('fc-nist-ai-rmf-govern-6-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','GOVERN 6.2','GOVERN','Third-party contingency processes','Contingency processes are in place to handle failures or incidents in third-party data or AI systems deemed to be high-risk.','governance','medium'),
  -- MAP
  ('fc-nist-ai-rmf-map-1-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 1.1','MAP','Context and intended purpose established','Intended purposes, potentially beneficial uses, context-specific laws, norms and expectations, and prospective settings in which the AI system will be deployed are understood and documented.','governance','high'),
  ('fc-nist-ai-rmf-map-1-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 1.2','MAP','Interdisciplinary AI actors','Interdisciplinary AI actors, competencies, skills, and capacities for establishing context reflect demographic diversity and broad domain and user experience expertise, and their participation is documented.','governance','medium'),
  ('fc-nist-ai-rmf-map-1-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 1.3','MAP','Mission and goals for AI','The organization''s mission and relevant goals for AI technology are understood and documented.','governance','medium'),
  ('fc-nist-ai-rmf-map-1-4','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 1.4','MAP','Business value defined','The business value or context of business use has been clearly defined or, in the case of assessing existing AI systems, re-evaluated.','governance','medium'),
  ('fc-nist-ai-rmf-map-1-5','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 1.5','MAP','Organizational risk tolerances','Organizational risk tolerances are determined and documented.','governance','high'),
  ('fc-nist-ai-rmf-map-1-6','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 1.6','MAP','System requirements elicited','System requirements are elicited from and understood by relevant AI actors, and design decisions take socio-technical implications into account to address AI risks.','governance','medium'),
  ('fc-nist-ai-rmf-map-2-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 2.1','MAP','Tasks and methods defined','The specific tasks and methods used to implement the tasks that the AI system will support are defined (e.g., classifiers, generative models, recommenders).','governance','medium'),
  ('fc-nist-ai-rmf-map-2-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 2.2','MAP','Knowledge limits and human oversight documented','Information about the AI system''s knowledge limits and how system output may be utilized and overseen by humans is documented.','governance','high'),
  ('fc-nist-ai-rmf-map-2-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 2.3','MAP','Scientific integrity and TEVV','Scientific integrity and TEVV considerations are identified and documented, including those related to experimental design, data collection and selection, system trustworthiness, and construct validation.','governance','medium'),
  ('fc-nist-ai-rmf-map-3-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 3.1','MAP','Potential benefits examined','Potential benefits of intended AI system functionality and performance are examined and documented.','governance','medium'),
  ('fc-nist-ai-rmf-map-3-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 3.2','MAP','Potential costs examined','Potential costs, including non-monetary costs, which result from expected or realized AI errors or system functionality and trustworthiness are examined and documented.','governance','medium'),
  ('fc-nist-ai-rmf-map-3-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 3.3','MAP','Application scope specified','Targeted application scope is specified and documented based on the system''s capability, established context, and AI system categorization.','governance','medium'),
  ('fc-nist-ai-rmf-map-3-4','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 3.4','MAP','Operator proficiency processes','Processes for operator and practitioner proficiency with AI system performance and trustworthiness, and relevant technical standards and certifications, are defined, assessed, and documented.','governance','medium'),
  ('fc-nist-ai-rmf-map-3-5','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 3.5','MAP','Human oversight processes','Processes for human oversight are defined, assessed, and documented in accordance with organizational policies from the GOVERN function.','governance','high'),
  ('fc-nist-ai-rmf-map-4-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 4.1','MAP','Mapping legal risks of components','Approaches for mapping AI technology and legal risks of its components, including the use of third-party data or software, are in place, followed, and documented.','governance','medium'),
  ('fc-nist-ai-rmf-map-4-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 4.2','MAP','Internal risk controls for components','Internal risk controls for components of the AI system, including third-party AI technologies, are identified and documented.','governance','medium'),
  ('fc-nist-ai-rmf-map-5-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 5.1','MAP','Impact likelihood and magnitude','Likelihood and magnitude of each identified impact (both potentially beneficial and harmful) based on expected use, past uses, public incident reports, feedback, or other data are identified and documented.','governance','high'),
  ('fc-nist-ai-rmf-map-5-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MAP 5.2','MAP','Engagement with AI actors','Practices and personnel for supporting regular engagement with relevant AI actors and integrating feedback about positive, negative, and unanticipated impacts are in place and documented.','governance','medium'),
  -- MEASURE
  ('fc-nist-ai-rmf-measure-1-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 1.1','MEASURE','Metrics selected for AI risks','Approaches and metrics for measurement of AI risks enumerated during the MAP function are selected for implementation starting with the most significant AI risks; risks that cannot be measured are documented.','technical','high'),
  ('fc-nist-ai-rmf-measure-1-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 1.2','MEASURE','Appropriateness of metrics assessed','Appropriateness of AI metrics and effectiveness of existing controls are regularly assessed and updated, including reports of errors and potential impacts on affected communities.','technical','medium'),
  ('fc-nist-ai-rmf-measure-1-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 1.3','MEASURE','Independent assessment','Internal experts who did not serve as front-line developers and/or independent assessors are involved in regular assessments and updates, consulting domain experts, users, and affected communities as necessary.','technical','medium'),
  ('fc-nist-ai-rmf-measure-2-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.1','MEASURE','TEVV documentation','Test sets, metrics, and details about the tools used during test, evaluation, verification, and validation (TEVV) are documented.','technical','medium'),
  ('fc-nist-ai-rmf-measure-2-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.2','MEASURE','Human subject evaluations','Evaluations involving human subjects meet applicable requirements (including human subject protection) and are representative of the relevant population.','technical','medium'),
  ('fc-nist-ai-rmf-measure-2-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.3','MEASURE','Performance measured','AI system performance or assurance criteria are measured qualitatively or quantitatively and demonstrated for conditions similar to deployment settings; measures are documented.','technical','high'),
  ('fc-nist-ai-rmf-measure-2-4','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.4','MEASURE','Production monitoring','The functionality and behavior of the AI system and its components, as identified in the MAP function, are monitored when in production.','technical','high'),
  ('fc-nist-ai-rmf-measure-2-5','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.5','MEASURE','Validity and reliability','The AI system to be deployed is demonstrated to be valid and reliable; limitations of the generalizability beyond the conditions under which the technology was developed are documented.','technical','high'),
  ('fc-nist-ai-rmf-measure-2-6','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.6','MEASURE','Safety evaluated','The AI system is evaluated regularly for safety risks and demonstrated to be safe, its residual negative risk does not exceed the risk tolerance, and it can fail safely, particularly if made to operate beyond its knowledge limits.','technical','high'),
  ('fc-nist-ai-rmf-measure-2-7','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.7','MEASURE','Security and resilience evaluated','AI system security and resilience, as identified in the MAP function, are evaluated and documented.','technical','high'),
  ('fc-nist-ai-rmf-measure-2-8','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.8','MEASURE','Transparency and accountability','Risks associated with transparency and accountability, as identified in the MAP function, are examined and documented.','technical','medium'),
  ('fc-nist-ai-rmf-measure-2-9','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.9','MEASURE','Model explainability','The AI model is explained, validated, and documented, and AI system output is interpreted within its context to inform responsible use and governance.','technical','medium'),
  ('fc-nist-ai-rmf-measure-2-10','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.10','MEASURE','Privacy risk examined','Privacy risk of the AI system, as identified in the MAP function, is examined and documented.','technical','high'),
  ('fc-nist-ai-rmf-measure-2-11','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.11','MEASURE','Fairness and bias evaluated','Fairness and bias, as identified in the MAP function, are evaluated and results are documented.','technical','high'),
  ('fc-nist-ai-rmf-measure-2-12','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.12','MEASURE','Environmental impact assessed','Environmental impact and sustainability of AI model training and management activities, as identified in the MAP function, are assessed and documented.','technical','low'),
  ('fc-nist-ai-rmf-measure-2-13','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 2.13','MEASURE','Effectiveness of TEVV','Effectiveness of the employed TEVV metrics and processes in the MEASURE function are evaluated and documented.','technical','medium'),
  ('fc-nist-ai-rmf-measure-3-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 3.1','MEASURE','Tracking emergent risks','Approaches, personnel, and documentation are in place to regularly identify and track existing, unanticipated, and emergent AI risks based on factors such as intended and actual performance in deployed contexts.','technical','high'),
  ('fc-nist-ai-rmf-measure-3-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 3.2','MEASURE','Risk tracking where metrics unavailable','Risk tracking approaches are considered for settings where AI risks are difficult to assess using currently available measurement techniques or where metrics are not yet available.','technical','medium'),
  ('fc-nist-ai-rmf-measure-3-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 3.3','MEASURE','User feedback processes','Feedback processes for end users and impacted communities to report problems and appeal system outcomes are established and integrated into AI system evaluation metrics.','technical','medium'),
  ('fc-nist-ai-rmf-measure-4-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 4.1','MEASURE','Measurement tied to deployment context','Measurement approaches for identifying AI risks are connected to deployment contexts and informed through consultation with domain experts and other end users; approaches are documented.','technical','medium'),
  ('fc-nist-ai-rmf-measure-4-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 4.2','MEASURE','Trustworthiness validated in deployment','Measurement results regarding AI system trustworthiness in deployment contexts and across the AI lifecycle are informed by input from domain experts and relevant AI actors to validate whether the system is performing consistently as intended.','technical','medium'),
  ('fc-nist-ai-rmf-measure-4-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MEASURE 4.3','MEASURE','Performance changes identified','Measurable performance improvements or declines based on consultations with relevant AI actors and field data about context-relevant risks and trustworthiness characteristics are identified and documented.','technical','medium'),
  -- MANAGE
  ('fc-nist-ai-rmf-manage-1-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 1.1','MANAGE','Proceed decision','A determination is made as to whether the AI system achieves its intended purposes and stated objectives and whether its development or deployment should proceed.','governance','high'),
  ('fc-nist-ai-rmf-manage-1-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 1.2','MANAGE','Risk treatment prioritized','Treatment of documented AI risks is prioritized based on impact, likelihood, and available resources or methods.','governance','high'),
  ('fc-nist-ai-rmf-manage-1-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 1.3','MANAGE','High-priority risk responses','Responses to the AI risks deemed high priority, as identified by the MAP function, are developed, planned, and documented; response options can include mitigating, transferring, avoiding, or accepting.','governance','high'),
  ('fc-nist-ai-rmf-manage-1-4','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 1.4','MANAGE','Residual risk documented','Negative residual risks (defined as the sum of all unmitigated risks) to both downstream acquirers of AI systems and end users are documented.','governance','medium'),
  ('fc-nist-ai-rmf-manage-2-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 2.1','MANAGE','Resources and alternatives considered','Resources required to manage AI risks are taken into account, along with viable non-AI alternative systems, approaches, or methods, to reduce the magnitude or likelihood of potential impacts.','governance','medium'),
  ('fc-nist-ai-rmf-manage-2-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 2.2','MANAGE','Sustaining value of deployed systems','Mechanisms are in place and applied to sustain the value of deployed AI systems.','governance','medium'),
  ('fc-nist-ai-rmf-manage-2-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 2.3','MANAGE','Responding to unknown risks','Procedures are followed to respond to and recover from a previously unknown risk when it is identified.','corrective','high'),
  ('fc-nist-ai-rmf-manage-2-4','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 2.4','MANAGE','Deactivation mechanisms','Mechanisms are in place and applied, and responsibilities are assigned and understood, to supersede, disengage, or deactivate AI systems that demonstrate performance or outcomes inconsistent with intended use.','corrective','high'),
  ('fc-nist-ai-rmf-manage-3-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 3.1','MANAGE','Third-party risk monitored','AI risks and benefits from third-party resources are regularly monitored, and risk controls are applied and documented.','governance','medium'),
  ('fc-nist-ai-rmf-manage-3-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 3.2','MANAGE','Pre-trained models monitored','Pre-trained models which are used for development are monitored as part of AI system regular monitoring and maintenance.','technical','medium'),
  ('fc-nist-ai-rmf-manage-4-1','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 4.1','MANAGE','Post-deployment monitoring plans','Post-deployment AI system monitoring plans are implemented, including mechanisms for capturing and evaluating input from users and other relevant AI actors, appeal and override, decommissioning, incident response, recovery, and change management.','detective','high'),
  ('fc-nist-ai-rmf-manage-4-2','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 4.2','MANAGE','Continual improvement','Measurable activities for continual improvements are integrated into AI system updates and include regular engagement with interested parties, including relevant AI actors.','governance','medium'),
  ('fc-nist-ai-rmf-manage-4-3','00000000-0000-0000-0000-000000000001','nist-ai-rmf','MANAGE 4.3','MANAGE','Incident communication','Incidents and errors are communicated to relevant AI actors, including affected communities; processes for tracking, responding to, and recovering from incidents and errors are followed and documented.','corrective','high')
ON CONFLICT (id) DO UPDATE SET
  control_ref = EXCLUDED.control_ref, domain = EXCLUDED.domain,
  title = EXCLUDED.title, description = EXCLUDED.description,
  control_type = EXCLUDED.control_type, priority = EXCLUDED.priority;

-- =====================================================================
-- 3. OWASP Top 10 for LLM Applications 2025  [framework_id: owasp-llm]
-- =====================================================================
INSERT INTO public.framework_controls
  (id, org_id, framework_id, control_ref, domain, title, description, control_type, priority)
VALUES
  ('fc-owasp-llm-llm01-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM01:2025','OWASP Top 10 for LLM Applications 2025','Prompt Injection','A user prompt alters the LLM''s behavior or output in unintended ways, whether directly or via injected content, potentially bypassing safety guidelines, generating harmful content, or enabling unauthorized access.','technical','high'),
  ('fc-owasp-llm-llm02-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM02:2025','OWASP Top 10 for LLM Applications 2025','Sensitive Information Disclosure','LLMs risk exposing sensitive data, proprietary algorithms, or confidential details through their output, leading to unauthorized data access, privacy violations, and intellectual property breaches.','technical','high'),
  ('fc-owasp-llm-llm03-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM03:2025','OWASP Top 10 for LLM Applications 2025','Supply Chain','LLM supply chains are susceptible to vulnerabilities affecting the integrity of training data, models, and deployment platforms, including risks from third-party pre-trained models, fine-tuning adapters, and dependencies.','technical','high'),
  ('fc-owasp-llm-llm04-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM04:2025','OWASP Top 10 for LLM Applications 2025','Data and Model Poisoning','Manipulation of pre-training, fine-tuning, or embedding data to introduce vulnerabilities, backdoors, or biases that compromise model security, performance, or ethical behavior.','technical','high'),
  ('fc-owasp-llm-llm05-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM05:2025','OWASP Top 10 for LLM Applications 2025','Improper Output Handling','Insufficient validation, sanitization, and handling of LLM-generated output before it is passed downstream, which can lead to XSS, CSRF, SSRF, privilege escalation, or remote code execution.','technical','high'),
  ('fc-owasp-llm-llm06-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM06:2025','OWASP Top 10 for LLM Applications 2025','Excessive Agency','Damaging actions performed in response to unexpected, ambiguous, or manipulated LLM output, caused by excessive functionality, permissions, or autonomy granted to LLM-based systems and their extensions.','technical','high'),
  ('fc-owasp-llm-llm07-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM07:2025','OWASP Top 10 for LLM Applications 2025','System Prompt Leakage','System prompts or instructions used to steer the model contain sensitive information that was not intended to be discovered, which when leaked can facilitate other attacks.','technical','medium'),
  ('fc-owasp-llm-llm08-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM08:2025','OWASP Top 10 for LLM Applications 2025','Vector and Embedding Weaknesses','Weaknesses in how vectors and embeddings are generated, stored, or retrieved in Retrieval Augmented Generation (RAG) systems can be exploited to inject harmful content, manipulate outputs, or access sensitive information.','technical','medium'),
  ('fc-owasp-llm-llm09-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM09:2025','OWASP Top 10 for LLM Applications 2025','Misinformation','LLMs produce false or misleading information that appears credible, including hallucinations and biased content, which can lead to security breaches, reputational damage, and legal liability when relied upon without oversight.','technical','high'),
  ('fc-owasp-llm-llm10-2025','00000000-0000-0000-0000-000000000001','owasp-llm','LLM10:2025','OWASP Top 10 for LLM Applications 2025','Unbounded Consumption','Excessive and uncontrolled inference that permits denial-of-service, economic loss (denial-of-wallet), model theft through extraction, or degradation of service by allowing unbounded resource consumption.','technical','medium')
ON CONFLICT (id) DO UPDATE SET
  control_ref = EXCLUDED.control_ref, domain = EXCLUDED.domain,
