-- =====================================================================
-- 4. Google Secure AI Framework (SAIF)  [framework_id: google-saif]
--    (a) the six SAIF core elements; (b) the 15 published SAIF Map risks.
-- =====================================================================
INSERT INTO public.framework_controls
  (id, org_id, framework_id, control_ref, domain, title, description, control_type, priority)
VALUES
  -- (a) six core elements
  ('fc-google-saif-element-1','00000000-0000-0000-0000-000000000001','google-saif','Element 1','SAIF Core Elements','Expand strong security foundations to the AI ecosystem','Leverage secure-by-default infrastructure protections and expertise built over decades to protect AI systems, applications and users, and extend those foundations to the AI ecosystem.','governance','high'),
  ('fc-google-saif-element-2','00000000-0000-0000-0000-000000000001','google-saif','Element 2','SAIF Core Elements','Extend detection and response to bring AI into an organization''s threat universe','Monitor the inputs and outputs of generative AI systems to detect anomalies and use threat intelligence to anticipate attacks, bringing AI into the organization''s threat universe.','detective','high'),
  ('fc-google-saif-element-3','00000000-0000-0000-0000-000000000001','google-saif','Element 3','SAIF Core Elements','Automate defenses to keep pace with existing and new threats','Use the latest AI innovations to improve the scale and speed of response efforts to security incidents, keeping automated defenses on pace with new and existing threats.','technical','medium'),
  ('fc-google-saif-element-4','00000000-0000-0000-0000-000000000001','google-saif','Element 4','SAIF Core Elements','Harmonize platform level controls to ensure consistent security across the organization','Ensure consistency across control frameworks and harmonize platform-level controls so that security mitigations are applied consistently across the organization''s AI systems.','governance','medium'),
  ('fc-google-saif-element-5','00000000-0000-0000-0000-000000000001','google-saif','Element 5','SAIF Core Elements','Adapt controls to adjust mitigations and create faster feedback loops for AI deployment','Continually test, learn, and adjust mitigations through reinforcement learning, red-teaming, and faster feedback loops for AI deployment.','corrective','medium'),
  ('fc-google-saif-element-6','00000000-0000-0000-0000-000000000001','google-saif','Element 6','SAIF Core Elements','Contextualize AI system risks in surrounding business processes','Conduct end-to-end risk assessments that contextualize AI system risks within the surrounding business processes, including data lineage, validation, and operational behavior monitoring.','governance','high'),
  -- (b) SAIF Map risks (real published risk ids)
  ('fc-google-saif-dp','00000000-0000-0000-0000-000000000001','google-saif','DP','SAIF Map Risks','Data Poisoning','Altering data sources used during training or retraining (by deleting, modifying, or injecting adversarial data) to degrade model performance, skew results, or create hidden backdoors.','technical','high'),
  ('fc-google-saif-utd','00000000-0000-0000-0000-000000000001','google-saif','UTD','SAIF Map Risks','Unauthorized Training Data','Training or fine-tuning a model using data that is not authorized for that use, which may violate policies, contracts, or regulations and pose legal or ethical challenges.','technical','medium'),
  ('fc-google-saif-mst','00000000-0000-0000-0000-000000000001','google-saif','MST','SAIF Map Risks','Model Source Tampering','Tampering with the model''s code, dependencies, weights, or associated data during development, comparable to maliciously modifying application source.','technical','high'),
  ('fc-google-saif-edh','00000000-0000-0000-0000-000000000001','google-saif','EDH','SAIF Map Risks','Excessive Data Handling','Unauthorized collection, retention, processing, or sharing of user data beyond what is necessary, raising privacy and compliance concerns.','technical','medium'),
  ('fc-google-saif-mxf','00000000-0000-0000-0000-000000000001','google-saif','MXF','SAIF Map Risks','Model Exfiltration','Theft of a model by an attacker who gains unauthorized access to the model itself, causing intellectual-property loss and potential financial harm.','technical','high'),
  ('fc-google-saif-mdt','00000000-0000-0000-0000-000000000001','google-saif','MDT','SAIF Map Risks','Model Deployment Tampering','Unauthorized changes to model deployment components (serving infrastructure, configuration, or artifacts) that alter model behavior in production.','technical','high'),
  ('fc-google-saif-dms','00000000-0000-0000-0000-000000000001','google-saif','DMS','SAIF Map Risks','Denial of ML Service','Overloading ML systems with resource-intensive queries to exhaust resources and degrade or deny service, analogous to a traditional denial-of-service attack.','technical','medium'),
  ('fc-google-saif-mre','00000000-0000-0000-0000-000000000001','google-saif','MRE','SAIF Map Risks','Model Reverse Engineering','Recreating or approximating a model by analyzing its inputs, outputs, and behaviors, undermining the confidentiality of the model.','technical','medium'),
  ('fc-google-saif-iic','00000000-0000-0000-0000-000000000001','google-saif','IIC','SAIF Map Risks','Insecure Integrated Component','Software vulnerabilities in components integrated with the AI system (plugins, extensions, agents, or tools) that can be leveraged to compromise AI models.','technical','high'),
  ('fc-google-saif-pij','00000000-0000-0000-0000-000000000001','google-saif','PIJ','SAIF Map Risks','Prompt Injection','Tricking a model into running unintended commands by exploiting confusion between instructions and input data, comparable in impact to code injection.','technical','high'),
  ('fc-google-saif-mev','00000000-0000-0000-0000-000000000001','google-saif','MEV','SAIF Map Risks','Model Evasion','Crafting changes to a prompt or input to cause the model to produce incorrect inferences (adversarial examples) and evade its intended behavior.','technical','high'),
  ('fc-google-saif-sdd','00000000-0000-0000-0000-000000000001','google-saif','SDD','SAIF Map Risks','Sensitive Data Disclosure','Disclosure of sensitive data by the model through its outputs, exposing confidential or personal information.','technical','high'),
  ('fc-google-saif-isd','00000000-0000-0000-0000-000000000001','google-saif','ISD','SAIF Map Risks','Inferred Sensitive Data','The model inferring personal or sensitive information that was not contained in the training data or inputs, creating new privacy exposure.','technical','medium'),
  ('fc-google-saif-imo','00000000-0000-0000-0000-000000000001','google-saif','IMO','SAIF Map Risks','Insecure Model Output','Unvalidated model output passed to downstream systems or the end user, which can trigger injection or other attacks if consumed without sanitization.','technical','high'),
  ('fc-google-saif-ra','00000000-0000-0000-0000-000000000001','google-saif','RA','SAIF Map Risks','Rogue Actions','Unintended model-based actions executed via extensions, agents, or plugins, whether by accident (misalignment) or maliciously (triggered via prompt injection).','technical','high')
