-- =====================================================================
-- Count sync + proof: set each framework's control_count to the real seeded
-- catalog size, and emit per-framework counts into the replay log.
-- =====================================================================
UPDATE public.frameworks f
SET control_count = (SELECT count(*) FROM public.framework_controls fc
                     WHERE fc.framework_id = f.id
                       AND fc.org_id = '00000000-0000-0000-0000-000000000001')
WHERE f.id IN ('iso-42001','nist-ai-rmf','owasp-llm','google-saif','mitre-atlas');

DO $$
DECLARE
  c_iso  int; c_nist int; c_owasp int; c_saif int; c_atlas int;
BEGIN
  SELECT count(*) INTO c_iso   FROM public.framework_controls WHERE framework_id='iso-42001'   AND org_id='00000000-0000-0000-0000-000000000001';
  SELECT count(*) INTO c_nist  FROM public.framework_controls WHERE framework_id='nist-ai-rmf' AND org_id='00000000-0000-0000-0000-000000000001';
  SELECT count(*) INTO c_owasp FROM public.framework_controls WHERE framework_id='owasp-llm'   AND org_id='00000000-0000-0000-0000-000000000001';
  SELECT count(*) INTO c_saif  FROM public.framework_controls WHERE framework_id='google-saif' AND org_id='00000000-0000-0000-0000-000000000001';
  SELECT count(*) INTO c_atlas FROM public.framework_controls WHERE framework_id='mitre-atlas' AND org_id='00000000-0000-0000-0000-000000000001';
  RAISE NOTICE 'Seeded framework_controls — iso-42001=%, nist-ai-rmf=%, owasp-llm=%, google-saif=%, mitre-atlas=%',
    c_iso, c_nist, c_owasp, c_saif, c_atlas;
END $$;
